'Custom_SMS_Guide_Title' => '設定方法',
'Custom_SMS_Guide_Intro' => 'HTTP API を備えた SMS プロバイダーであれば接続できます。プロバイダーの API ドキュメントを開き、エンドポイント、メソッド、フィールド名をコピーして、プレースホルダーを使って以下に対応付けてください。',
