'Custom_SMS_Guide_Method' => '最も一般的なのは POST です。プロバイダーがすべてを URL で受け取る場合のみ GET を選択してください。その場合、ペイロードのフィールドはクエリパラメーターとして送信されます。',
'Custom_SMS_Guide_Content_Type' => '「json」はペイロードを JSON ボディ（application/json）として送信します。「form」は従来の HTML フォーム（application/x-www-form-urlencoded）として送信します。プロバイダーがどちらを想定しているか確認してください。GET の場合は無視されます。',
'Custom_SMS_Guide_Sender' => '承認済みの送信者 ID または送信用の電話番号です。この値は {sender} プレースホルダーに入るだけなので、実際に送信するにはペイロード、ヘッダー、または URL で使用する必要があります。',
'Custom_SMS_Guide_Success_Keyword' => '任意ですが推奨します。送信に失敗しても「200 OK」を返すプロバイダーがあります。成功時のレスポンスにのみ含まれる単語や文字列（例：success）を入力してください。レスポンスにそれが含まれない場合、SMS は失敗として扱われます。',
'Custom_SMS_Guide_Headers' => 'プロバイダーが求める認証ヘッダーです（例：Authorization = Bearer YOUR_API_KEY、または Api-Key = YOUR_API_KEY）。Content-Type は自動的に設定されるため追加しないでください。',
'Custom_SMS_Guide_Payload' => 'リクエストボディのフィールドです。名前はプロバイダーのドキュメントの記載どおりにしてください。値にはプレースホルダーを使用します（例：to = {phone}、message = {message}、from = {sender}）。',
