'Cr_Guide_B_Booking' => '「配送業者に送信」では、受取人、住所、代金引換としての未払い額、商品の重量が販売から入力されます。独自の都市リストを持つ配送業者では選択欄が表示され、選択内容はその都市について記憶されます。アグリゲーター、DHL、FedEx、UPS、Lalamove では「料金を比較」が使用でき、料金を選んで「発送依頼」を押すと購入されます。販売一覧から複数の販売を一括で発送依頼することもできます。',
'Cr_Guide_T_Cod' => '代金引換',
'Cr_Guide_B_Cod' => '代金引換の荷物は、「未回収」から（配達時に）「配送業者が回収済み」、さらに「精算済み」へと進みます。精算を報告する配送業者では最後のステップが自動で進みます。それ以外の配送業者では「代金引換を更新」を使用してください。「配送業者設定」で口座を選択している場合、精算は販売の支払いとして記録されます。配送料金は、荷物が完了した時点で費用として保存できます。',
'Cr_Guide_T_Returns' => '返送された荷物',
'Cr_Guide_B_Returns' => '既定では、返送された荷物は「配送業者の出荷」の「確認待ちの返送」で待機します。「在庫に戻す」は注文全体の販売返品を作成して商品を在庫に戻します。「却下」は何も戻さず、破損または紛失した荷物に使用します。「配送業者設定」で自動的に在庫に戻すように設定することもできます。',
'Cr_Guide_T_Customers' => '顧客へのメッセージと追跡ページ',
'Cr_Guide_B_Customers' => '「配送業者設定」の顧客通知では、チェックを入れたステータスで SMS、メール、WhatsApp を荷物ごとに 1 回、独自の文面で送信します。オンラインストアの追跡ページでは、顧客が追跡番号、または注文番号と電話番号で荷物を追跡できます。返品の多い顧客には、発送依頼時に返品リスクのバッジが表示されます。',
'Cr_Guide_T_Labels' => 'ラベル',
'Cr_Guide_B_Labels' => '「ラベルを印刷」では、配送業者が独自のラベル（PDF、リンク、画像）を発行する場合はそれを、発行しない場合は追跡バーコードと回収金額入りの Stocky ラベルを出力します。印刷するには、このサイトのポップアップを許可してください。DHL、FedEx、UPS はラベルを発送依頼時に 1 回だけ発行するため、Stocky が再印刷用に保管します。',
'Cr_Guide_T_Faq' => 'トラブルシューティング',
'Cr_Guide_Q_Test' => '接続テストが失敗する',
'Cr_Guide_A_Test' => 'テスト用のキーはテストモード、本番用のキーは本番モードで使用します。これらは異なるキーです。正確な原因は「配送業者ログ」で配送業者の応答を確認してください。',
'Cr_Guide_Q_City' => '配送業者が都市名または住所を受け付けない',
'Cr_Guide_A_City' => '発送依頼フォームで配送業者の都市リストから都市を選択してください。配送業者は独自の名称しか受け付けません。郵便住所を使用する配送業者では、都道府県／州、郵便番号、2 文字の国コードも必要です。',
'Cr_Guide_Q_Webhook' => 'ステータスが自動で変わらない',
'Cr_Guide_A_Webhook' => '更新を送信する配送業者の場合は、Webhook URL が配送業者側に登録されていることを確認してください。「配送業者ログ」には、受信したすべての更新や拒否された理由（シークレットの誤りなど）が表示されます。その他の配送業者は「配送業者設定」のスケジュールで確認され、「今すぐステータスを確認」ですぐに問い合わせることもできます。',
'Cr_Guide_Q_Stuck' => '出荷にステータス確認エラーが表示される',
'Cr_Guide_A_Stuck' => '配送業者が直近の確認を拒否しました。理由は出荷と「配送業者ログ」に表示されます。失敗が繰り返されると、その出荷は自動確認の対象外になります。原因を解決してから「今すぐステータスを確認」を使用してください。',
'Cr_Guide_Q_Label' => 'ラベルを印刷しても何も開かない',
'Cr_Guide_A_Label' => 'ブラウザーがポップアップをブロックしました。このサイトのポップアップを許可して、もう一度お試しください。',
'Cr_Guide_Q_Cod' => '代金引換の精算が販売に記録されない',
'Cr_Guide_A_Cod' => '「配送業者設定」で、代金引換のスイッチをオンにして口座を選択する必要があります。口座がない場合、精算は精算済みとしてマークされるだけです。',
