'Tg_Guide_B_Body' => '次の2種類のメッセージは、Telegram 専用のキューで待機します。1つは送信に失敗したもの（Telegram に一時的に接続できない場合）で、その後数分間に最大3回まで再試行されます。もう1つは管理画面以外で発生したイベント（WooCommerce や Shopify から取り込んだ注文、artisan コマンドなど）です。この Cron の設定はこれらを送信するだけで、それ以外は何もしません：',
