'Woo_Automatic_Sync' => '自動同期',
'Woo_Auto_Sync_Intro' => 'このページを開かなくても、Stocky での変更を発生と同時に WooCommerce へ送信します。各送信は操作の保存直後に実行されるため、レジ担当者が WooCommerce を待つことはありません。結果は「ログ」タブに表示されます。',
'Woo_Auto_Sync_Products_Help' => 'Stocky で作成・編集・複製した商品を WooCommerce に送信します（詳細、価格、バリエーション、画像、在庫）。一括インポートは送信されません。インポート後は「商品」タブの「同期 — POS → WooCommerce」を使用してください。',
'Woo_Auto_Sync_Stock_Help' => '在庫の動き（POS 販売、販売、返品、仕入、調整、移動）があると、対象商品の WooCommerce 上の数量を更新します。更新されるのは、すでに WooCommerce と紐付けられている商品のみです。',
'Woo_Sync_Tuning' => '同期の調整',
'Woo_Sync_Tuning_Intro' => 'ほとんどのストアは既定値で問題ありません。ご利用のホスティングで同期が遅い、またはタイムアウトする場合にのみ変更してください。各値は安全な範囲に制限され、欄を空にすると既定値に戻ります。',
'Woo_Sync_Guide' => 'WooCommerce 同期ガイド',
'Woo_Guide_Getting_Keys' => 'API キーの取得',
'Woo_Guide_Keys_1' => 'WooCommerce で WooCommerce → Settings → Advanced → REST API を開きます。',
'Woo_Guide_Keys_2' => '「Add key」をクリックし、「Read/Write」を選択してから、「Consumer key」と「Consumer secret」をコピーします。',
'Woo_Guide_Keys_3' => 'ストアの URL：末尾にスラッシュを付けないサイトの URL です（例：{example}）。',
'Woo_Guide_WP_Title' => 'WP ユーザー名とアプリケーションパスワード（任意）',
'Woo_Guide_WP_Intro' => 'これらの項目は商品画像にのみ使用されます。WooCommerce API（ストアの URL ＋ Consumer key/secret）が商品、在庫、カテゴリ、ブランド、顧客、注文の同期を担い、WordPress REST API がメディアライブラリ（画像の検索とアップロード）を担います。',
'Woo_Guide_WP_1' => '商品や在庫を同期する際、Stocky は商品画像を添付できます。まずファイル名で WordPress のメディアライブラリから既存の画像を検索し、見つからない場合は WordPress API で画像をアップロードします。',
'Woo_Guide_WP_2' => 'メディアを管理できる WordPress ユーザー（例：Administrator）を使用してください。WordPress の Users → Profile（またはご自身のユーザー）→ Application Passwords でアプリケーションパスワードを作成し、新しく追加したものをここに貼り付けます。',
'Woo_Guide_WP_3' => 'これらを空欄にしても、すべてのデータ（商品、在庫、カテゴリ、ブランド、顧客、注文）の同期は動作します。省略されるのは商品画像の添付（検索 / アップロード）のみです。',
'Woo_Guide_How_To_Enable' => '有効にする方法',
'Woo_Guide_Enable_1' => '上でストアの URL、Consumer key、Consumer secret を入力し、「保存」をクリックします。',
'Woo_Guide_Enable_2' => '「接続をテスト」で認証情報を確認します。',
'Woo_Guide_Enable_3' => '同期が必要なときは、各タブから手動同期を実行します。',
'Woo_Guide_Enable_4' => '上の「自動同期」をオンにすると、新規・編集した商品とすべての在庫変更が発生と同時に WooCommerce へ送信されます。',
'Woo_Guide_Manual_Sync' => '手動同期（必要に応じて）',
'Woo_Guide_Manual_1' => '同期は双方向で動作します：Stocky → WooCommerce と WooCommerce → Stocky。',
'Woo_Guide_Manual_2' => '手動同期は WooCommerce のすべてのタブ（商品、在庫など）で利用できます。各タブの同期操作で必要なときに同期を実行してください。',
'Woo_Guide_Auto_1' => '商品：オンの場合、Stocky で作成・編集・複製した商品は保存直後に WooCommerce へ送信され、続いて在庫も送信されます。',
'Woo_Guide_Auto_2' => '在庫：オンの場合、すべての在庫変更（POS 販売、販売、返品、仕入、調整、移動）で WooCommerce 上の数量が更新されます。更新されるのは、すでに WooCommerce と紐付けられている商品のみです。',
'Woo_Guide_Auto_3' => '自動同期は Stocky から WooCommerce への送信のみを行います。WooCommerce から Stocky へのデータ取得（注文、顧客、商品）は、常に「注文」「顧客」「商品」タブのボタンで行います。',
'Woo_Guide_Auto_4' => '商品の一括インポートは自動送信されません。インポート後は「商品」タブの「同期 — POS → WooCommerce」を使用してください。',
'Woo_Guide_Auto_5' => '自動送信はすべて「ログ」タブに記録されるため、送信内容を確認し、エラーを見つけることができます。',
'Woo_Guide_First_Setup' => '初回セットアップ',
'Woo_Guide_First_1' => '既存のカタログを紐付けるため、次の操作を一度だけ、この順序で実行してください：「カテゴリ」タブの「同期 — POS → WooCommerce」、次に「ブランド」タブ、次に「商品」タブ、最後に「在庫」タブの「在庫を同期」。その後、上の「自動同期」をオンにして WooCommerce を最新の状態に保ちます。',
'Woo_Guide_First_2' => '大量の商品・在庫の同期は小さなバッチで実行され、タブに進捗が表示されます。同期が終わるまでページを開いたままにしてください。いつでも停止できます。',
'Woo_Guide_First_3' => '同期が数分間進まない場合は、「ログ」タブを確認してから、サポートにお問い合わせください。',
'Woo_Guide_Notes_1' => 'ストアの URL や API キーを変更すると、マッピング（商品、カテゴリ、ブランド、顧客）がリセットされ、項目は（新しい）ストアに再度同期されます。',
'Woo_Guide_Notes_2' => '商品の重複を避け、安全に再紐付けできるよう、Stocky と WooCommerce の SKU を一致させてください。',
