'Shp_G_Push_Note' => '送信されるのは、Shopify マッピングがすでにある商品の、このストアの倉庫での動きのみです。一括操作（商品の削除、倉庫のリセットなど）はイベントを発生させずに在庫を書き込むため、スケジュールされた在庫ステップも残しておくことをお勧めします。',
'Shp_G_Nothing_Else' => 'ほかにインストールするものはありません',
'Shp_G_Nothing_Else_Body' => 'どちらもキューワーカーや cron エントリは不要です。受信する Webhook は Shopify からのリクエスト内で処理され、送信する在庫は販売を処理したのと同じプロセスで、応答が返された{after}に実行されます。そのためレジが Shopify を待つことはなく、応答しなくなったショップは 10 秒で打ち切られ、次回のスケジュールされた在庫送信に任されます。',
'Shp_G_After' => '後',
'Shp_G_Exception' => '例外が 1 つあります。バックグラウンドタスクによる在庫変更には後に続く応答がないため、代わりに {queue} キューに登録されます。',
'Shp_G_Queue_Managed' => 'プラットフォームがすでにそのキューでワーカーを実行しているため、これらも自動で送信されます。',
'Shp_G_Queue_Cron' => 'これらもすぐに送信したい場合は、そのキューを処理してください：',
'Shp_G_On_Schedule' => 'スケジュール',
'Shp_G_On_Lc' => 'オン',
'Shp_G_Off_Lc' => 'オフ',
'Shp_G_Scheduled_Lead' => 'すべてが一定間隔で双方向に再確認されます。リアルタイムより遅いものの、即時送信を使わないショップに在庫を送信し、漏れた Webhook を補い、カタログ全体を移動できる唯一の方法です。',
'Shp_G_Nothing_To_Install' => 'インストール不要',
'Shp_G_Managed_Body' => 'スケジューラーは自動で実行されます。5 分ごとにプラットフォームが各ストアに同期プランのステップで実行予定のものがあるかを確認し、該当するものを実行します。cron エントリの追加やサーバーの管理は不要です。',
'Shp_G_Managed_Note' => 'ステップ間隔の最短が 5 分のため、同期プランで使える最小単位も 5 分です。それより長い間隔は正確に守られます。30 分に設定したステップは 6 回確認され、1 回実行されます。',
'Shp_G_Cron_Entry' => 'cron エントリ',
'Shp_G_Cron_Body' => 'これがないと、スケジュールされたものは何も実行されません。このモジュール専用の 1 行を、ほかにスケジュールしているものと並べて追加してください：',
'Shp_G_Cron_Note' => 'ステップ間隔の最短が 5 分のため、同期プランで使える最小単位は 5 分ごとです。より粗いエントリにすると、それが下限になります。{every15} の場合、5 分に設定したステップは 15 分ごとに実行されます。Windows ではタスク スケジューラを使用し、プログラムに {php}、引数に {args}、開始場所に {path} を指定してください。',
'Shp_G_Switch_On' => 'オンにして、同期プランを選択します',
'Shp_G_Plan_Body' => '{path} スイッチはスケジューラーが動作してよいかどうかを決め、同期プランは何を行うかを決めます。{step}とは、独自の間隔を持つ 1 つのデータ種別の 1 方向の同期です（{ex1}、{ex2} など）。既定の間隔は、間隔欄が空のステップで使用されます。',
'Shp_G_Step_Lc' => 'ステップ',
'Shp_G_Ex1' => '注文 · Shopify → ERP 15 分ごと',
'Shp_G_Ex2' => '在庫 · ERP → Shopify 30 分ごと',
'Shp_G_Plan_Note' => '同期プランを空のままにすると、ストアは既定の間隔で注文を取得し在庫を送信します。ほとんどのショップにはこれで十分です。注文は取得のみです。顧客が注文するのは Shopify だからです。',
'Shp_G_Schedule_On' => 'スケジュール オン',
'Shp_G_Schedule_Off' => 'スケジュール オフ（手動のみ）',
'Shp_G_When_Runs' => 'ステップが実際に実行されるタイミング',
'Shp_G_When_Body' => '同じステップが最後に{started}時点から間隔以上経過すると、そのステップは実行予定になります。これは実行履歴から判断されます。そのため、手動で開始した同期は次回の自動実行を後ろにずらし、失敗し続けるステップは毎回ではなく間隔ごとに再試行されます。ストアの概要には、各ステップの最終実行、次回予定時刻、ブロックされている場合はその理由が表示されます。最初のカタログ送信は、スケジュールに組み込む前に、まずドライランで同期センターから手動で実行してください。',
'Shp_G_Started_Lc' => '開始された',
'Shp_G_Where_Setting' => '各設定の場所',
'Shp_G_Where_Note' => 'これらはすべて既存のストアにあります：{path} で鉛筆アイコンをクリックします（またはストアのページで {edit}）。',
'Shp_G_Product_Images' => '商品画像',
'Shp_G_Img1' => '画像は{push}時に商品と一緒に送信されます。メイン画像が最初、次にギャラリー、その後独自の画像を持つバリエーションごとに 1 枚ずつ、最大 50 枚までです。',
'Shp_G_Products_Push' => '商品の送信',
'Shp_G_Img2' => 'バリエーションの画像は商品と一緒にアップロードされた後、{assigned}。これは Shopify のモデルに沿ったもので、バリエーションは商品の画像の 1 つを参照します。メイン画像を再利用するバリエーションでは、二重にアップロードされることはありません。',
'Shp_G_Assigned' => 'そのバリエーションに割り当てられます',
'Shp_G_Img3' => 'ファイルとして保存された画像は、リンクではなく Shopify に{uploaded}されるため、このシステムにインターネットからアクセスできない場合でも機能します。貼り付けたリンクとして追加された画像はその URL のまま Shopify に渡されるため、公開されている必要があります。',
'Shp_G_Uploaded' => 'アップロード',
'Shp_G_Img4' => '画像が再送信されるのは、実際に変更された場合のみです。送信すると画像一式が置き換わるため、価格だけを変更する送信ではショップの画像には触れません。',
