'Agt_Guide_What_Body' => '完了した販売はすべてAGT電子請求書（作成時に支払済みの場合は FR、それ以外は FT）として、受領済みの返品はすべてクレジットノート（NC）として発行されます。各書類にはAGTシリーズの次の番号が付与され、AGT鍵で署名されてAGTに送信され、数分後にAGTが検証します。レシートとPDF請求書には、AGT番号、セキュリティ抜粋、QRコードが印刷されます。',
