'Comm_G_T_Stacking' => '1回の販売に複数のルールがある場合',
'Comm_G_Stacking_Body' => 'ルールの組み合わせ方はプログラムごとに決まります（プログラムの「複数のルールが一致した場合」設定）。

最も優先度の高いルールのみ支払う（新しいプログラムのデフォルト）：優先度の高い順にルールが試され、その販売で最初に対象となったルールが支払われます。販売が最低しきい値に達し、結果が0より大きい場合に、ルールは対象となります。これにより段階制を簡単に作れます。たとえば、優先度10で「10,000以上の販売に7%」、優先度0で「5%」とします。Saraに特別な料率を適用するには、「全エージェント」ルールより優先度の高い、Sara用の「特定のエージェント」ルールを追加します。

一致するすべてのルールで支払う：一致するすべてのルールで支払われ、金額が合算されます。3%の「全エージェント」ルールと、Sara用の2%の「特定のエージェント」ルールがある場合、Saraは5%を獲得します。

プログラムは互いに独立しています。有効なプログラムはそれぞれ個別に支払うため、1回の販売で基本プログラムとキャンペーンプログラムの両方からコミッションが発生することがあります。',
'Comm_G_T_Paying' => 'コミッション領収書でエージェントに支払う',
'Comm_G_Paying_Body' => '「コミッション領収書」を開いて「追加」をクリックします。エージェントを選ぶと、その「承認済み」コミッションが一覧表示されます。支払うものにチェックを入れると、「金額」に合計が入力されます（調整も可能です）。「参照」は自動で入力され（CR-000001、CR-000002...）、支払い方法、日付、メモを追加できます。

領収書を保存すると、チェックしたコミッションが「支払済」になり、領収書に紐付けられます。支払えるのは「承認済み」のコミッションのみなので、先にコミッションレポートで承認してください。

マイナスの調整（エージェントに過払いした金額）も一覧に表示されます。エージェントの次のコミッションと一緒にチェックを入れると、その支払いから差し引かれます。

領収書は支払いの記録にすぎず、費用を作成したり、勘定間で資金を移動したりはしません。費用や会計で支払いを管理している場合は、そちらにも記録してください。',
'Comm_G_T_Snapshot' => '販売が変更された場合',
'Comm_G_Snapshot_Body' => 'コミッションは販売に連動します。コミッションのある販売が変更されると、現在の数値（販売合計から受領済みの返品を差し引いた額、支払額から返金を差し引いた額）に基づいて再計算されます。

未払いのコミッション（「保留中」または「承認済み」）は、そのまま更新されます。金額が変わった「承認済み」コミッションは、再確認のため「保留中」に戻ります。支払義務がなくなったもの（販売の削除、全数返品、エージェントの変更）は削除されます。

支払済のコミッションが変更されることはありません。差額は「調整」と表示された新しい「保留中」の行になります。追加の支払義務がある場合（例：「支払済金額」の販売で残額が支払われた）はプラス、エージェントに過払いした場合（例：返品後）はマイナスです。承認して、エージェントの次の領収書に含めてください。

各コミッションは、最初に獲得した時点のルールの条件（種類、料率、しきい値、上限）を保持します。後からルールを変更またはオフにしても、再計算時に過去の販売の金額は変わりません。',
'Comm_G_T_Permissions' => '権限ごとにできること',
'Comm_G_Permission' => '権限',
'Comm_G_Lets_You' => 'できること',
'Comm_G_P_View' => 'コミッションのすべてのページ（プログラム、エージェント、ルール、領収書、レポート、このガイド）を表示できます。',
'Comm_G_P_Add' => 'プログラム、エージェント、ルールを作成し、コミッション領収書を記録（エージェントへの支払い）できます。',
'Comm_G_P_Edit' => 'プログラム、エージェント、ルールを編集し、コミッションレポートでコミッションを承認またはキャンセルできます。',
'Comm_G_P_Delete' => 'プログラム、エージェント、ルールを削除できます。',
'Comm_G_T_Faq' => 'よくある質問',
'Comm_G_Q_Empty' => 'すべて設定したのに、コミッションレポートが空です。',
'Comm_G_A_Empty' => '次の点を確認してください：販売がルールの作成後に保存されていること、販売が「完了」であること、販売にエージェントがいること（販売で選択されているか、販売したユーザーがエージェントに紐付けられている）、プログラムが有効で販売日がその期間内であること、ルールが有効でそのエージェントに適用されること、販売がルールの最低しきい値以上であること。また、レポートの日付フィルターも確認してください。これはコミッションが計算された日付で絞り込みます。',
'Comm_G_Q_Twice' => '1回の販売でエージェントに2件のコミッションが付きました。',
'Comm_G_A_Twice' => '2つのルールで支払われています。プログラムが「一致するすべてのルールで支払う」に設定されているか、ルールが2つの異なる有効なプログラムにあります（各プログラムは個別に支払います）。1つだけ支払うようにするには、プログラムを「最も優先度の高いルールのみ支払う」に設定してください。販売を再度保存しても、コミッションが重複することはありません。',
'Comm_G_Q_Rate' => 'ルールの料率を変更すると、過去のコミッションも変わりますか？',
'Comm_G_A_Rate' => 'いいえ。各コミッションは、獲得時のルールの条件を保持します。後から販売が再計算された場合も同様です。新しい料率は、今後獲得されるコミッションに使用されます。',
'Comm_G_Q_Return' => '顧客が商品を返品しました。コミッションはどうなりますか？',
'Comm_G_A_Return' => '自動的に減額されます。受領済みの返品は販売合計を、返金は支払額を減らします。コミッションがまだ支払われていない場合は更新されます（全数返品の場合は削除）。すでに支払われている場合は、マイナスの調整が追加され、エージェントの次の領収書から差し引かれます。',
'Comm_G_Q_Wrong_Agent' => '誤ったエージェントに計上してしまいました。どう修正すればよいですか？',
'Comm_G_A_Wrong_Agent' => '販売を編集して正しい販売エージェントを選び、保存してください。コミッションは正しいエージェントに移ります。最初のエージェントにすでに支払っていた場合は、そのエージェントにマイナスの調整が追加されます。',
'Comm_G_Q_Inactive' => 'エージェントを無効にするとどうなりますか？',
'Comm_G_A_Inactive' => '新しい販売でコミッションを獲得しなくなり、エージェントの選択肢から非表示になります。既存のコミッションは残り、引き続き承認・支払いが可能で、販売の変更にも連動します。そのエージェントを選択して保存された販売が、別のエージェントに移ることはありません。',
'Comm_G_Q_Partial' => '「支払済金額」ルールでは、一部支払いはどう扱われますか？',
'Comm_G_A_Partial' => '未払いの販売ではコミッションは発生しません。コミッションは最初に入金があったとき（会計時または支払いの追加時）に作成され、支払いが増えるにつれて増額されます。一部がすでに支払われている場合、残りはプラスの調整として追加されます。',
'Comm_G_Q_Undo' => '支払いやキャンセルを取り消せますか？',
'Comm_G_A_Undo' => '支払いは取り消せません。「支払済」は確定で、領収書は編集も削除もできないため、保存前にチェックしたコミッションと金額を確認してください。キャンセルは取り消せます。コミッションレポートで行にチェックを入れて「再計算」をクリックするか、「販売を編集」で販売を再度保存してください。',
'Comm_G_Q_Dates' => 'プログラムの期間にはどの日付が使われますか？',
'Comm_G_A_Dates' => '保存した日ではなく、販売自体の日付です。先月の日付の販売には、先月有効だったプログラムのみが使用されます。',
'Comm_G_When_Changes' => 'その後、コミッションのある販売に変更があると、コミッションは自動的に更新されます：支払いの編集・削除、返品と返金、ステータスが「完了」以外になった場合、または販売の削除。',
'Comm_G_F_Program_Mode' => 'このプログラム内の複数のルールが同じ販売に一致した場合の動作です。「最も優先度の高いルールのみ支払う」：優先度の高い順にルールが試され、最初に対象となったルールが支払われます。「一致するすべてのルールで支払う」：すべてのルールで支払われ、金額が合算されます。',
'Comm_G_Q_Mode_Old' => '優先度を設定したのに、ルールが合算されてしまいます。',
'Comm_G_A_Mode_Old' => 'そのプログラムは「一致するすべてのルールで支払う」に設定されています。この設定が追加される前に作成されたプログラムは、支払額が変わらないようにその動作を維持しています。プログラムを編集して「最も優先度の高いルールのみ支払う」を選択してください。',
'Comm_G_Q_Negative' => 'マイナスのコミッションがあるのはなぜですか？',
'Comm_G_A_Negative' => 'これは「調整」です。返品、返金、合計の減少、エージェントの変更、販売の削除により、販売で現在発生する額よりも多くエージェントに支払われています。承認して、エージェントの次の領収書でチェックを入れると差し引かれます。',
'Comm_Rule_Mode' => '複数のルールが一致した場合',
'Comm_Mode_Highest' => '最も優先度の高いルールのみ支払う',
'Comm_Mode_All' => '一致するすべてのルールで支払う（合算）',
'Comm_Mode_Highest_Short' => '最高優先度のルールを適用',
'Comm_Mode_All_Short' => 'ルールを合算',
'Comm_Mode_Highest_Help' => '優先度の高い順にルールが試され、その販売で最初に対象となったルールが支払われ、他はスキップされます。段階制に適しています。たとえば、優先度10で10,000を超える場合に7%、優先度0でそれ以外すべてに5%とします。',
'Comm_Mode_All_Help' => 'エージェントに一致するすべてのルールがその販売で支払われるため、金額が合算されます。優先度は順序を決めるだけです。',
'Comm_Priority_Help_Highest' => 'このプログラムでは、対象となるルールのうち最も優先度の高いもののみが支払われます。優先させたいルールよりも高い優先度をこのルールに設定してください。同じ値の場合は、「特定のエージェント」ルールが「全エージェント」ルールより優先されます。',
'Comm_Priority_Help_All' => 'このプログラムでは一致するすべてのルールが支払われるため、このルールは他のルールに加算されます。優先度は順序を決めるだけです。',
'Comm_Recalculate' => '再計算',
'Comm_Recalculate_Help' => 'チェックした行の販売を、現在の数値に基づいて再計算します。キャンセル済みのコミッションも対象です。',
'Comm_Adjustment' => '調整',
'Comm_Adjustment_Help' => '支払済のコミッションに対する修正です。後から販売が変更されたために発生します。マイナスの金額は、エージェントの次の領収書から差し引かれます。',
'Comm_Cancel_Confirm' => '選択したコミッションをキャンセルしますか？',
'Comm_Cancel_Confirm_Help' => 'これらは支払われず、後から支払いや返品があってもキャンセルのままです。「販売を編集」で販売を保存するか、「再計算」をクリックすると、再度計算されます。',
'Fashion_Tiles_Hint' => '独自のタイル（画像、タイトル、リンク）を追加すると、自動のカテゴリタイルの代わりに表示されます。',

