'Rst_Guide_Step_First_Help' => 'フロアプランでテスト用のテーブルにお客様を案内し、料理を追加して送信し、キッチンディスプレイで完成にしてから支払いを受け付けます。',
'Rst_Guide_Step_Qr' => 'QRテーブル注文',
'Rst_Guide_Step_Qr_On' => 'オン。{n} テーブルにQRコードがあります。',
'Rst_Guide_Step_Qr_Help' => 'お客様がテーブルのコードを読み取り、スマートフォンで料理を選んで、テーブルの注文に送信します。レストラン設定でオンにしてから、コードを印刷してください。',
'Rst_Guide_Step_Booking' => 'オンラインテーブル予約',
'Rst_Guide_Step_Booking_On' => 'オン。オンラインストアからの予約は「予約」に届くので、確定してください。',
'Rst_Guide_Step_Booking_Help' => 'お客様がオンラインストアからテーブルを予約できるようにします。予約受付時間、間隔、最大人数はレストラン設定で設定します。',
'Rst_Guide_Step_Store' => 'オンラインストアと「レストラン」テーマ',
'Rst_Guide_Step_Store_On' => '「レストラン」テーマが有効です。オンライン注文がキッチンに届くタイミング：{mode}。',
'Rst_Guide_Step_Store_Help' => '「オンラインストア › 設定」で「レストラン」テーマを選択すると、ホームページがメニューになり、アドオン、持ち帰り／デリバリー、テーブル予約が使えます。',
'Rst_Guide_How' => '使い方',
'Rst_Guide_Service' => '営業の流れ（ステップごと）',
'Rst_Guide_Service_1_T' => '案内',
'Rst_Guide_Service_1' => 'フロアプランで空いているテーブルを選び、人数とウェイターを入力して、「お客様を案内して注文を受ける」を押します。予約のあるグループは、その予約から案内します。',
'Rst_Guide_Service_2_T' => '注文',
'Rst_Guide_Service_2' => '注文画面で料理をタップします。アドオン、座席、コースを選び、キッチンへのメモを追加します。コースを保留して、後から調理を開始することもできます。',
'Rst_Guide_Service_3_T' => '送信',
'Rst_Guide_Service_3' => '「送信」を押すと、新しい料理が1枚のキッチンチケットにまとめられます。未送信の料理は変更や削除ができますが、送信後は理由を付けて取消することしかできません。',
'Rst_Guide_Service_4_T' => '調理',
'Rst_Guide_Service_4' => 'キッチンディスプレイには、各ステーションにチケットが表示されます。調理担当者はチケットを開始し、できあがった料理にチェックを入れ、すべて完成したらバンプします。',
'Rst_Guide_Service_5_T' => '提供',
'Rst_Guide_Service_5' => '完成した料理はフロアプランと注文画面に表示されます。ウェイターが料理を運び、「提供済みにする」をタップします。',
'Rst_Guide_Service_6_T' => '会計',
'Rst_Guide_Service_6' => '「伝票・会計」で伝票を印刷し、支払いを受け付けます。一括、均等割り、品目ごとの支払いが可能です。各支払いは通常のPOS販売として記録されます。',
'Rst_Guide_Service_7_T' => '片付け',
'Rst_Guide_Service_7' => 'すべての支払いが済むと注文が閉じられ、テーブルは「要清掃」になります（レストラン設定によっては、直接「空席」になります）。',
'Rst_Guide_Roles' => '担当業務と権限',
'Rst_Guide_Roles_Help' => 'レストランの権限は「グループ権限」でロールごとに付与します。1人のユーザーに複数のロール分の権限を持たせることもできます。',
'Rst_Guide_Job' => '業務',
'Rst_Guide_Give' => '付与する権限',
'Rst_Guide_Job_Waiter' => 'ウェイター',
'Rst_Guide_Job_Cook' => '調理担当',
'Rst_Guide_Job_Cashier' => 'レジ担当',
'Rst_Guide_Job_Host' => '案内係／受付',
'Rst_Guide_Job_Supervisor' => 'スーパーバイザー',
'Rst_Guide_Job_Manager' => 'マネージャー',
'Rst_Guide_Menu' => 'メニュー、ステーション、アドオン',
'Rst_Guide_Menu_1' => '販売するすべての商品を料理にできます。「レストラン › メニュー」（または商品フォームの「料理の詳細」カード）でレストラン用の情報を追加します。',
'Rst_Guide_Menu_2' => 'アドオングループには価格付きの選択肢をまとめます（例：「サイズ」（1つ選択）、「トッピング」（3つまで））。ルールはオンライン注文も含め、すべての注文で確認されます。',
'Rst_Guide_Menu_3' => 'アドオンで材料を消費させることもできます。「チーズ追加」を「チーズ」商品に紐付けると、1つごとにその在庫が引き落とされます。',
'Rst_Guide_Menu_4' => 'スイッチ1つで料理を本日売り切れにできます。翌日には自動的に元に戻ります。食事の時間帯（朝食、昼食、夕食）で、料理を提供する時間を制限できます。',
'Rst_Guide_Menu_5' => 'レシピはコンボ商品として作成します。仮想コンボ在庫がオンの場合、料理を販売するとその構成品が在庫から引き落とされます。',
'Rst_Guide_Kitchen' => 'キッチンディスプレイ',
'Rst_Guide_Kitchen_1' => 'キッチンの画面で「レストラン › キッチン」を開き、ステーションを選択します。ステーションが設定されていない料理は、すべてのステーションに表示されます。',
'Rst_Guide_Kitchen_2' => 'チケットは待ち時間に応じて黄色、続いて赤色に変わります（「レストラン設定 › チケットの遅延判定」）。新しいチケットはビープ音でお知らせします。',
'Rst_Guide_Kitchen_3' => '開始 → 料理にチェック → バンプ。「このステーションで完了」を押すと、共有チケットのうちこのステーションの料理だけが完了になります。',
'Rst_Guide_Kitchen_4' => '提供済みのチケットは15分間残るため、間違えた場合は呼び戻せます。チケットは80 mmプリンターで印刷できます。',
'Rst_Guide_Kitchen_5' => 'オンラインストアやテーブルQRコードからの注文は、チケットに「オンライン」または「QRコード」と表示されます。',
'Rst_Guide_Bills' => '伝票と支払い',
'Rst_Guide_Bills_1' => '各支払いは通常のPOS販売です。在庫、レジ、会計、ロイヤルティポイント、電子インボイスはPOSと同じように処理されます。',
'Rst_Guide_Bills_2' => 'サービス料は、店内飲食（設定によってはすべての注文）の料理の税抜金額に対する割合です。チップは、あらかじめ設定した割合または金額で指定します。',
'Rst_Guide_Bills_3' => '割引には「伝票の割引」権限が必要で、上限はレストラン設定の「割引の上限」で決まります。',
'Rst_Guide_Bills_4' => '端数処理は、伝票を精算する支払いで、お客様に有利になるよう設定した単位で切り捨てられます。',
'Rst_Guide_Bills_5' => '均等割り：1件の販売に、1人につき1行の支払いが記録されます（1セント単位で分配）。品目ごと：各お客様の料理がそれぞれ別の販売になります。座席を選ぶと、その座席の料理が選択されます。',
'Rst_Guide_Bills_6' => '伝票の表示後に内容が変わった場合（QRコードから料理が追加された、チップが変更されたなど）、支払いは拒否されます。そのため、お客様が確認していない金額を請求することはありません。',
'Rst_Guide_Bills_7' => '支払済みの料理は取消できません。注文の未払い分がすべて取消されると、注文は支払済みとして閉じられ、テーブルをクリアできます。',
'Rst_Guide_Bookings' => '予約と順番待ち',
'Rst_Guide_Bookings_1' => '予約では、その利用時間の間テーブルが確保されます（デフォルトはレストラン設定で指定）。1つのテーブルで2つの予約が重なることはありません。',
'Rst_Guide_Bookings_2' => 'フロアプランには各テーブルの次の予約が表示され、時刻が近づくと警告が出ます。「来店 — 案内」でグループを案内します。',
'Rst_Guide_Bookings_3' => '無断キャンセル扱いの時間を過ぎると、遅れているグループを無断キャンセルにできます。間違えた場合は復元できます。',
'Rst_Guide_Bookings_4' => '順番待ちリストでは、予約なしのお客様を目安の待ち時間とともに順番に管理します。テーブルの準備ができたら電話またはWhatsAppで連絡し、案内します。',
'Rst_Guide_Bookings_5' => 'オンライン予約は「予約済み」として届き（サイドバーのバッジに件数が表示されます）、確定を待ちます。',
'Rst_Guide_Online' => 'オンライン注文、QRメニュー、オンライン予約',
'Rst_Guide_Online_1' => '「レストラン」ストアテーマでは、オンラインストアのホームページがアドオンと食事タグのフィルター付きのメニューになります。お客様は通常どおりチェックアウトで支払います。',
'Rst_Guide_Online_2' => '「オンライン注文をキッチンに送るタイミング」で、注文がキッチンディスプレイに届くタイミングを決めます。注文時（支払済み、またはログイン済みの顧客による配達時／受け取り時払い）、受付時、または送らない、から選べます。',
'Rst_Guide_Online_3' => 'テーブルQRコード（「フロア設定 › テーブルQRコード」）を読み取ると、そのテーブル用のメニューが開きます。「新しいリンク」を押すと、印刷済みのコードは無効になります。',
'Rst_Guide_Online_4' => '「QR注文をキッチンに直接送信」がオンでない限り、QR注文はウェイターが送信するまでテーブルの注文で待機します。お支払いはスタッフが受け付けます。',
'Rst_Guide_Online_5' => 'オンライン予約では、人数に合うテーブルが予約時間中ずっと空いている時刻のみが表示されます。また、1つの電話番号につき今後の予約は3件までに制限されます。',
'Rst_Guide_Online_6' => 'これらはすべてオンラインストアの機能です。オンラインストアがオンになっていて、プランに含まれている必要があります。',
'Rst_Guide_Reports' => 'ダッシュボードとレポート',
'Rst_Guide_Reports_1' => 'ダッシュボードには、本日の数値が先週の同じ曜日と比較して表示されます（売上、伝票数、客数、平均伝票額、取消、割引）。さらに、現在の状況も表示されます。',
'Rst_Guide_Reports_2' => '売上は、レストランの伝票と、キッチンに届いたオンライン注文の合計です。料理の売上と粗利は税抜で、各商品の原価を使用します。',
'Rst_Guide_Reports_3' => 'レポート：日別・支払い方法別の売上、料理、取消とキャンセル（理由付き）、スタッフ、調理時間、予約。いずれもExcelにエクスポートできます。',
'Rst_Guide_Reports_4' => '一部の支店に限定されたスタッフには、その支店のデータのみが表示されます。支店のない注文は全員に共有されます。',
'Rst_Guide_Faq' => '知っておくと便利なこと',
'Rst_Guide_Faq_1_Q' => '「送信」を押す前にテイクアウトの支払いが済みました。調理されますか？',
'Rst_Guide_Faq_1_A' => 'はい。支払うと、まだ送信されていない料理がキッチンに送信されます。',
'Rst_Guide_Faq_2_Q' => 'テーブルをクリアできないのはなぜですか？',
'Rst_Guide_Faq_2_A' => 'そのテーブルの注文に未払いの料理が残っています。支払いを受け付けるか、食べなかった料理を取消するか、注文をキャンセルしてください（キャンセルは何も支払われていない場合のみ）。',
'Rst_Guide_Faq_3_Q' => '2つのテーブルを寄せました。それぞれの注文はどうなりますか？',
'Rst_Guide_Faq_3_A' => '「テーブルを結合」を使うと、2つ目のテーブルの料理（と支払い）がメインテーブルの注文に移動します。「分離」でテーブルを再び分けられます。',
'Rst_Guide_Faq_4_Q' => 'ここでのカード支払いにStripeを使えますか？',
'Rst_Guide_Faq_4_A' => 'いいえ。Stripeのカード支払いにはPOSのカードフォームが必要です。カード端末を使う場合は「カード」などの支払い方法を追加し、伝票でそれを使用してください。',
'Rst_Guide_Faq_5_Q' => 'ある料理が1つの支店でだけ在庫切れです。',
'Rst_Guide_Faq_5_A' => '在庫は注文の支店（テーブルのエリア、なければレストラン設定のデフォルト支店）から引き落とされます。すぐに注文を止めるには「本日売り切れ」を使用してください。',
'Rst_Guide_Faq_6_Q' => 'プリンターは必要ですか？',
'Rst_Guide_Faq_6_A' => 'いいえ。伝票、レシート、キッチンチケットは、ブラウザからどのプリンターでも印刷できます。80 mmのレシートプリンターが最適です。',
'Rst_Guide_Faq_7_Q' => 'オンラインストアのレストランメニューはどこから作られますか？',
'Rst_Guide_Faq_7_A' => '同じ商品、カテゴリ、アドオンから作られます。オンラインストアで非表示の商品や、ストアに表示されないカテゴリは、オンラインメニューとQRメニューには表示されません。',

