'Mkg_Guide_Faq_5_Q' => '「送信済み」は顧客が受け取ったという意味ですか？',
'Mkg_Guide_Faq_5_A' => '「送信済み」は、メールサーバーまたはゲートウェイがメッセージを受け付けたという意味です。受信トレイへの到達、開封、迷惑メールフィルターは追跡されません。',
'Mkg_Guide_Faq_6_Q' => '送信後にキャンペーンを編集できますか？',
'Mkg_Guide_Faq_6_A' => 'いいえ。送信中および送信済みのキャンペーンはロックされます。代わりに新しいキャンペーンを作成してください。',
'Mkg_Guide_Faq_7_Q' => 'WhatsAppのメッセージが届きません。',
