'Mkg_Guide_Faq_8_Q' => 'キャンペーンを再送信すると、顧客に2回届きますか？',
'Mkg_Guide_Faq_8_A' => '止まったキャンペーンを再開した場合は、まだ保留中の受信者にのみ送信されるため、すでに届いた人に再送されることはありません。失敗したキャンペーンを再送信した場合は、新しいリストで最初からやり直します。',

