'Pd_Single_Payment' => '一括払い',
'Pd_Guide_How_Title' => '仕組み',
'Pd_Guide_How_Intro' => 'POSデバイスとは、レジの横に置くカード端末または税務レジのことです。Stockyはデバイスに金額を送信し、顧客の支払いを待ち、デバイスが承認した後にのみ支払いを記録します。',
'Pd_Guide_Step_1' => 'ここでデバイスを追加します：モデル、倉庫、そしてカード支払いを記録する支払い方法（例：「クレジットカード」）を指定します。',
'Pd_Guide_Step_2' => 'Stockyがデバイスに接続する方法を選択します：レジ用コンピューター上のローカルブリッジ、またはプロバイダーのクラウドAPIです。銀行またはプロバイダーから提供されたIDとキーを入力してください。',
'Pd_Guide_Step_3' => '「接続テスト」を押します。ブリッジ接続のデバイスは、ブリッジが動作しているレジ用コンピューターからテストする必要があります。',
'Pd_Guide_Step_4' => 'POSでその支払い方法を選び、「デバイスで決済」を押して顧客に支払ってもらいます。デバイスが承認すると販売を完了できます。',
'Pd_Guide_Step_5' => '「取引」で販売なしで行われたカード支払い（例：途中で放棄された会計）を確認し、取消または返金を行います。',
'Pd_Guide_Bridge_Text' => 'レジ用PC上のベンダーSDKで操作するデバイス（USB、シリアル、LANペアリング）向けです。ブラウザはSDKを直接使用できないため、小さなブリッジプログラムがSDKをラップし、このコンピューター上で待ち受けます。',
'Pd_Guide_Bridge_Point_1' => 'POSはレジ担当のブラウザから各リクエストをブリッジURLに送信します。Stockyのサーバーがショップのネットワークに接続する必要はありません。',
'Pd_Guide_Bridge_Point_2' => 'リクエストと応答は共有シークレットで署名されるため、ブラウザから承認を偽装することはできません。',
'Pd_Guide_Bridge_Point_3' => 'このデバイスでカード支払いを受け付けるすべてのコンピューターに、ブリッジをインストールして起動してください。',
'Pd_Guide_Cloud_Text' => 'インターネット経由でデバイスに接続するプロバイダー向けです。StockyのサーバーがAPIを呼び出すため、レジ用コンピューターに何もインストールする必要はありません。',
'Pd_Guide_Cloud_Point_1' => 'API URLは、公開アドレス上の https:// である必要があります。',
'Pd_Guide_Cloud_Point_2' => '顧客が支払っている間、Stockyは2秒ごとにステータスを問い合わせるため、ステータスエンドポイントは参照番号で支払いを識別できる必要があります。カード処理が終わる前にAPIが応答した場合（"pending"）は、ポーリングで結果が決まります。',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'IDE280は、カードリーダーを搭載した新世代の税務レジ（YN ÖKC）です。通常は、IngenicoのECR / GMP3 SDK、または銀行の連携サービスを通じて連携します。',
'Pd_Guide_Ide280_Point_1' => 'Ingenico／銀行のドキュメントに従ってデバイスをレジ用コンピューターとペアリングし、ブリッジ（またはAPI設定）をそのデバイスに向けてください。',
'Pd_Guide_Ide280_Point_2' => '金額は小数とクルシュ単位（amount_minor）の両方で、通貨 TRY / 949 として送信されます。',
'Pd_Guide_Ide280_Point_3' => '「完全な税務レシート」では、各商品にVAT税率に対応するデバイスの部門が付与されます。VAT部門はデバイスのプログラム設定に合わせてください。',
'Pd_Guide_Protocol_Title' => 'ブリッジ／API仕様',
'Pd_Guide_Protocol_Intro' => 'StockyはブリッジまたはAPIとJSONで通信します。以下のパスは既定値で、デバイスごとに「詳細設定」で変更できます。',
'Pd_Guide_Operation' => '操作',
