'Pd_Guide_When' => 'タイミング',
'Pd_Guide_When_Ping' => '「接続テスト」ボタン。',
'Pd_Guide_When_Sale' => 'レジ担当が「デバイスで決済」を押したとき。カード処理の完了時に応答しても、すぐにステータス "pending" で応答しても構いません。',
'Pd_Guide_When_Status' => '支払いが保留中の間、2秒ごと。',
'Pd_Guide_When_Cancel' => 'カード待機中にレジ担当がキャンセルしたとき。',
'Pd_Guide_When_Void' => '支払いを取り消すとき（当日、全額）。',
'Pd_Guide_When_Refund' => '支払いの一部または全額を返金するとき。',
'Pd_Guide_Request_Title' => 'リクエスト',
'Pd_Guide_Request_Text' => '販売時にStockyが送信する本文です。返金と取消では、元の支払いが "original" として含まれます。',
'Pd_Guide_Response_Title' => '応答',
'Pd_Guide_Response_Text' => 'フィールド名は柔軟に読み取られます（"data" 配下も対象）。"status" または response_code "00" で結果が決まります。カード番号はマスクして保存されます。',
