'Ord_Guide_PayAuto_Intro' => 'この列は、注文のうちどれだけが支払われたかを示します。顧客がチェックアウトで選んだ方法から始まり、注文を確認すると作成される販売に支払いが記録されるたびに自動的に更新されます。このページから編集することはできません。',
