'Ord_Guide_PayAuto_Note' => 'ここに表示される支払いステータスは販売に連動します。支払いを保存すると自動的に「一部支払済」または「支払済」に変わり、支払いを削除すると元に戻ります。販売が会計上の記録であり、支払いレポートと利益レポートの元データになります。入力した内容の確認や編集は、販売の「支払いを表示」から行ってください。',
