'Oc_G_Variants_3' => 'OpenCart 3 にはバリエーションがなくオプションのみで、在庫はオプション値ごとに管理されます。オプションが 1 つ（例：Size）の商品は値ごとの在庫で同期され、こちらのバリエーションに対応します。オプションが複数ある商品は、組み合わせごとの在庫なしでオプションが作成されます。在庫は商品全体で管理され、販売明細は商品に対して計上されます。',
'Oc_G_Variants_Multi' => 'オプションのみでバリエーションが作成されていないストア商品は 1 つの商品として取り込まれ、その旨がログに記録されます。',
'Oc_G_T_Stock' => '在庫',
