'Oc_G_Stock_2' => '1時間に1回、リンク済みのすべての商品を確認して修正します。これにより、リアルタイム送信では検知できない一括変更もカバーされます。「在庫」タブでは、いつでもすべてを送信できます。',
'Oc_G_Stock_3' => 'サービス、常に在庫ありに設定された商品、構成品が無制限のコンボ商品は、ストアで常に購入可能として表示されます。「接続」タブで倉庫を選ぶとその倉庫だけを集計し、選ばない場合はすべての倉庫を合計します。',
'Oc_G_T_Orders' => '注文とステータス',
