'Oc_G_Default_Cancel' => 'Canceled、Denied、Failed、Refunded、Reversed、Chargeback、Expired、Voided',
'Oc_G_Orders_2' => 'リストは初回接続時にストアの情報から設定され、「接続」タブで変更できます。両方が同じ段階で在庫を動かすよう、最初のリストは OpenCart で在庫を減らすステータスと同じにしてください。',
'Oc_G_Orders_3' => 'どの商品とも一致しない品目を含む注文は保留され、ストアにその商品があれば取り込まれます。保留中の注文は定期確認のたびに再試行され、12回試行しても失敗した場合はログに記録され、手動での取得を待ちます。',
'Oc_G_T_Cancel' => 'キャンセルと返金',
'Oc_G_Cancel_1' => 'ストアで注文がキャンセル系のステータスになると、ここでの販売は取り消されます。在庫が戻り、支払いが削除され、販売は削除されます。「販売」ページで削除した場合とまったく同じです。',
'Oc_G_Cancel_2' => 'すでに配送済み、返品あり、または税務当局に受理された販売は、ストアから取り消されることはありません。確認できるよう、販売のメモとログにフラグが付きます。',
